                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF lower(NEW.email) = 'blindadoemotivado@gmail.com' THEN                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin')                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
