                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF _amount = 0 THEN RETURN; END IF;                                                                                                                                                                                                                                                                                             +
