 can_access_track             | _user uuid, _track uuid                              | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.can_access_track(_user uuid, _track uuid)                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |  RETURNS boolean                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE sql                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   SELECT public.plan_rank(public.current_plan(_user)) >= public.plan_rank(                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     COALESCE((SELECT required_plan FROM public.tracks WHERE id = _track), 'free')                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   );                                                                                                                                                                                                                                                                                                                              +
