                              |                                                      |                  |            |                             | 
 check_achievements           | _user uuid                                           | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.check_achievements(_user uuid)                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  RETURNS void                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_modules_done INTEGER;                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   v_streak INTEGER;                                                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   v_xp INTEGER;                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   v_perfect_streak INTEGER := 0;                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   v_track_complete BOOLEAN := false;                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   r RECORD;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   SELECT COUNT(*) INTO v_modules_done FROM public.module_progress WHERE user_id = _user AND completed = true;                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   SELECT COALESCE(streak,0), COALESCE(xp,0) INTO v_streak, v_xp FROM public.profiles WHERE id = _user;                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Perfeccionista: streak atual de quizzes 100% (últimas tentativas por módulo)                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   FOR r IN                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     SELECT DISTINCT ON (module_id) module_id, score, created_at                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |       FROM public.quiz_attempts                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |       WHERE user_id = _user                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       ORDER BY module_id, created_at DESC                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   LOOP                                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     IF r.score = 100 THEN                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |       v_perfect_streak := v_perfect_streak + 1;                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END LOOP;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Trilheiro: existe alguma trilha em que TODOS os cursos publicados foram certificados?                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |   SELECT EXISTS (                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     SELECT 1                                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     FROM public.tracks t                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     WHERE (                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       SELECT COUNT(*) FROM public.courses c WHERE c.track_id = t.id AND c.is_published                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     ) > 0                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     AND NOT EXISTS (                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |       SELECT 1 FROM public.courses c                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |       WHERE c.track_id = t.id AND c.is_published                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |         AND NOT EXISTS (                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |           SELECT 1 FROM public.certificates ce                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |           WHERE ce.user_id = _user AND ce.course_id = c.id AND ce.revoked_at IS NULL                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |         )                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     )                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   ) INTO v_track_complete;                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_modules_done >= 1 THEN                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_achievements (user_id, achievement_id)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       SELECT _user, id FROM public.achievements WHERE code = 'first_step'                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |       ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_streak >= 7 THEN                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_achievements (user_id, achievement_id)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       SELECT _user, id FROM public.achievements WHERE code = 'full_week'                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |       ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_perfect_streak >= 3 THEN                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_achievements (user_id, achievement_id)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       SELECT _user, id FROM public.achievements WHERE code = 'perfectionist'                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |       ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_track_complete THEN                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_achievements (user_id, achievement_id)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       SELECT _user, id FROM public.achievements WHERE code = 'trailblazer'                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |       ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_xp >= 2500 THEN                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     INSERT INTO public.user_achievements (user_id, achievement_id)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       SELECT _user, id FROM public.achievements WHERE code = 'master_fcia'                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |       ON CONFLICT DO NOTHING;                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 compute_level                | _xp integer                                          | f                | i          | -                           | CREATE OR REPLACE FUNCTION public.compute_level(_xp integer)                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |  RETURNS text                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE sql                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  IMMUTABLE                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   SELECT CASE                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     WHEN _xp >= 2500 THEN 'Mestre FCIA'                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |     WHEN _xp >= 1000 THEN 'Especialista'                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     WHEN _xp >= 500 THEN 'Praticante'                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     WHEN _xp >= 200 THEN 'Explorador'                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     ELSE 'Iniciante'                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   END                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 current_plan                 | _user uuid                                           | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.current_plan(_user uuid)                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |  RETURNS text                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE sql                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   SELECT COALESCE((                                                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |     SELECT plan_id FROM public.subscriptions                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     WHERE user_id = _user                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |       AND status = 'active'                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       AND (expires_at IS NULL OR expires_at > now())                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |     ORDER BY started_at DESC                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     LIMIT 1                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   ), 'free');                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 enforce_course_publish_rules |                                                      | f                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.enforce_course_publish_rules()                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_published_modules INTEGER;                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF NEW.is_published = true THEN                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     IF NEW.title IS NULL OR length(btrim(NEW.title)) = 0                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |        OR NEW.description IS NULL OR length(btrim(NEW.description)) < 40                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |        OR NEW.slug IS NULL OR length(btrim(NEW.slug)) = 0 THEN                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |       RAISE EXCEPTION 'Curso não pode ser publicado sem título, slug e promessa principal (descrição com pelo menos 40 caracteres).';                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     IF NEW.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |       RAISE EXCEPTION 'Slug inválido. Use apenas minúsculas, números e hífens (ex.: venda-com-ia).';                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     IF NEW.is_free = false AND (NEW.price IS NULL OR NEW.price <= 0) THEN                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |       RAISE EXCEPTION 'Curso/ebook não pode ser publicado sem preço definido. Marque como gratuito ou informe um preço maior que zero.';                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     IF NEW.cover_url IS NULL OR NEW.cover_url !~* '^(https?://|/).+' THEN                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |       RAISE EXCEPTION 'Curso/ebook não pode ser publicado sem capa. Envie uma imagem ou informe uma URL válida.';                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     IF NEW.product_type = 'ebook' THEN                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |       IF NEW.delivery_url IS NULL OR length(btrim(NEW.delivery_url)) = 0 THEN                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |         RAISE EXCEPTION 'Ebook não pode ser publicado sem link de entrega (delivery_url).';                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |       END IF;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     ELSE                                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |       IF NEW.workload_hours IS NULL OR NEW.workload_hours <= 0 THEN                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |         RAISE EXCEPTION 'Curso não pode ser publicado sem carga horária definida (workload_hours > 0).';                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |       END IF;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |       SELECT COUNT(*) INTO v_published_modules                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |         FROM public.modules                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |        WHERE course_id = NEW.id AND is_published = true;                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |       IF v_published_modules < 3 THEN                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |         RAISE EXCEPTION 'Curso precisa de pelo menos 3 módulos publicados para ir ao ar. Publicados agora: %.', v_published_modules;                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |       END IF;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 enforce_quiz_unlocked        |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.enforce_quiz_unlocked()                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_course uuid;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   v_elig RECORD;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   v_course := NEW.course_id;                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   IF v_course IS NULL THEN                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     SELECT course_id INTO v_course FROM public.modules WHERE id = NEW.module_id;                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |     NEW.course_id := v_course;                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_course IS NULL THEN                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'course_required_for_attempt';                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Executa como o próprio usuário do attempt para respeitar sua elegibilidade                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   IF NEW.user_id IS DISTINCT FROM auth.uid() THEN                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'user_mismatch';                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT * INTO v_elig FROM public.get_quiz_eligibility(v_course);                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   IF NOT v_elig.quiz_unlocked THEN                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'quiz_locked: conclua todos os módulos do curso para liberar o quiz.';                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 enroll_in_course             | _course_id uuid                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.enroll_in_course(_course_id uuid)                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |  RETURNS enrollments                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user UUID := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_course RECORD;                                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   v_plan TEXT;                                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   v_required TEXT;                                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   v_enrollment public.enrollments;                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'Not authenticated';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT c.id, c.track_id, c.price, t.required_plan                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |     INTO v_course                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     FROM public.courses c                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     LEFT JOIN public.tracks t ON t.id = c.track_id                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     WHERE c.id = _course_id AND c.is_published = true;                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_course.id IS NULL THEN                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'Course not found';                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Cursos pagos (compra avulsa) só podem ser matriculados pelo webhook de pagamento                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |   IF COALESCE(v_course.price, 0) > 0 THEN                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'purchase_required';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   v_plan := public.current_plan(v_user);                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   v_required := COALESCE(v_course.required_plan, 'free');                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF public.plan_rank(v_plan) < public.plan_rank(v_required) THEN                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'plan_required:%', v_required;                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   INSERT INTO public.enrollments (user_id, course_id, track_id, plan_at_enrollment)                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   VALUES (v_user, _course_id, v_course.track_id, v_plan)                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   ON CONFLICT (user_id, course_id)                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     DO UPDATE SET last_accessed_at = now(), updated_at = now()                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   RETURNING * INTO v_enrollment;                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   RETURN v_enrollment;                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 get_bonus_download_path      | _bonus_id uuid                                       | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.get_bonus_download_path(_bonus_id uuid)                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |  RETURNS text                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user UUID := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_course UUID;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   v_path TEXT;                                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   v_published BOOLEAN;                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'not_authenticated';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT course_id, pdf_path, is_published                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     INTO v_course, v_path, v_published                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     FROM public.course_bonuses                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |    WHERE id = _bonus_id;                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_course IS NULL OR v_published IS NOT TRUE THEN                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'bonus_unavailable';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF NOT (public.has_course_access(v_user, v_course) OR public.has_role(v_user, 'admin')) THEN                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'no_access';                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Registra o download (idempotente por chamada — cada request loga uma linha)                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   INSERT INTO public.bonus_downloads (user_id, bonus_id) VALUES (v_user, _bonus_id);                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   RETURN v_path;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 get_module_intro_video_path  | _module_id uuid                                      | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.get_module_intro_video_path(_module_id uuid)                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |  RETURNS TABLE(video_path text, poster_path text)                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user uuid := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_course uuid;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   v_published boolean;                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |   v_video text;                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   v_poster text;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'not_authenticated';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   SELECT course_id, is_published, intro_video_path, intro_video_poster_path                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     INTO v_course, v_published, v_video, v_poster                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     FROM public.modules                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |    WHERE id = _module_id;                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF v_course IS NULL OR v_published IS NOT TRUE THEN                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'module_unavailable';                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF NOT (public.has_course_access(v_user, v_course) OR public.has_role(v_user, 'admin')) THEN                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'forbidden';                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN QUERY SELECT v_video, v_poster;                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 get_module_pdf_path          | _module_id uuid                                      | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.get_module_pdf_path(_module_id uuid)                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |  RETURNS text                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user UUID := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_course UUID;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   v_path TEXT;                                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'not_authenticated';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   SELECT course_id, pdf_path INTO v_course, v_path                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     FROM public.modules WHERE id = _module_id;                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   IF v_course IS NULL THEN                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'module_not_found';                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   IF NOT public.has_course_access(v_user, v_course) THEN                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'forbidden';                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN v_path;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
