                              |                                                      |                  |            |                             | 
 get_quiz_eligibility         | _course_id uuid                                      | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.get_quiz_eligibility(_course_id uuid)                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |  RETURNS TABLE(enrolled boolean, total_required_modules integer, completed_required_modules integer, completion_percent integer, quiz_unlocked boolean, block_reason text)                                                                                                                                                        +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user uuid := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_enrolled boolean := false;                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   v_total int := 0;                                                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   v_done int := 0;                                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   v_access boolean := false;                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RETURN QUERY SELECT false, 0, 0, 0, false, 'not_authenticated'::text;                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     RETURN;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   v_access := public.has_course_access(v_user, _course_id);                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   v_enrolled := EXISTS (                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     SELECT 1 FROM public.enrollments WHERE user_id = v_user AND course_id = _course_id                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |   ) OR v_access;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF NOT v_access THEN                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     RETURN QUERY SELECT v_enrolled, 0, 0, 0, false, 'no_access'::text;                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     RETURN;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT COUNT(*) INTO v_total                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     FROM public.modules                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |    WHERE course_id = _course_id AND is_published = true;                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_total = 0 THEN                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     RETURN QUERY SELECT v_enrolled, 0, 0, 0, false, 'no_modules_configured'::text;                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     RETURN;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT COUNT(*) INTO v_done                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     FROM public.module_progress mp                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     JOIN public.modules m ON m.id = mp.module_id                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |    WHERE mp.user_id = v_user                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |      AND mp.course_id = _course_id                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |      AND mp.completed = true                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |      AND m.is_published = true;                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   RETURN QUERY SELECT                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     v_enrolled,                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     v_total,                                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     v_done,                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     CASE WHEN v_total = 0 THEN 0 ELSE ROUND((v_done::numeric / v_total::numeric) * 100)::int END,                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     (v_done >= v_total),                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     CASE WHEN v_done >= v_total THEN NULL ELSE 'modules_pending' END;                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 grant_paid_access            | _user_id uuid, _plan_id text, _course_id uuid        | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.grant_paid_access(_user_id uuid, _plan_id text, _course_id uuid DEFAULT NULL::uuid)                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |  RETURNS void                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_plan TEXT := COALESCE(NULLIF(_plan_id, ''), 'free');                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   v_track UUID;                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   v_subscription_id UUID;                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   v_expires TIMESTAMPTZ;                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   v_is_course_purchase BOOLEAN := (v_plan = 'course_purchase');                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF _user_id IS NULL THEN                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'user_required';                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Compra avulsa: apenas cria enrollment no curso, sem alterar plano/subscription                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   IF v_is_course_purchase THEN                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     IF _course_id IS NULL THEN                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |       RAISE EXCEPTION 'course_required_for_course_purchase';                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     SELECT track_id INTO v_track FROM public.courses WHERE id = _course_id;                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     INSERT INTO public.enrollments (user_id, course_id, track_id, plan_at_enrollment)                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     VALUES (_user_id, _course_id, v_track, 'course_purchase')                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     ON CONFLICT (user_id, course_id)                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |       DO UPDATE SET plan_at_enrollment = 'course_purchase',                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |                     last_accessed_at = now(),                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |                     updated_at = now();                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |     RETURN;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Fluxo de assinatura (plano recorrente)                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   SELECT id, expires_at INTO v_subscription_id, v_expires                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   FROM public.subscriptions                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   WHERE user_id = _user_id                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     AND status = 'active'                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     AND provider = 'asaas'                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     AND (expires_at IS NULL OR expires_at > now())                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   ORDER BY started_at DESC                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |   LIMIT 1;                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_subscription_id IS NULL THEN                                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |     INSERT INTO public.subscriptions (user_id, plan_id, status, provider, started_at, expires_at)                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     VALUES (_user_id, v_plan, 'active', 'asaas', now(), now() + interval '30 days');                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   ELSE                                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     UPDATE public.subscriptions                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |        SET plan_id = v_plan,                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |            status = 'active',                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |            expires_at = CASE                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |              WHEN v_expires IS NULL OR v_expires < now() + interval '25 days'                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |                THEN now() + interval '30 days'                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |              ELSE v_expires                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |            END,                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |            updated_at = now()                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |      WHERE id = v_subscription_id;                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   UPDATE public.profiles                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |      SET plan = v_plan,                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |          updated_at = now()                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |    WHERE id = _user_id;                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF _course_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |     SELECT track_id INTO v_track FROM public.courses WHERE id = _course_id;                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     INSERT INTO public.enrollments (user_id, course_id, track_id, plan_at_enrollment)                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     VALUES (_user_id, _course_id, v_track, v_plan)                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |     ON CONFLICT (user_id, course_id)                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |       DO UPDATE SET plan_at_enrollment = v_plan,                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |                     last_accessed_at = now(),                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |                     updated_at = now();                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 handle_new_user              |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.handle_new_user()                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   INSERT INTO public.profiles (id, full_name, avatar_url)                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   VALUES (                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     NEW.id,                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.raw_user_meta_data ->> 'name'),                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     NEW.raw_user_meta_data ->> 'avatar_url'                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |   );                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 has_course_access            | _user uuid, _course uuid                             | t                | s          | search_path=public, pg_temp | CREATE OR REPLACE FUNCTION public.has_course_access(_user uuid, _course uuid)                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  RETURNS boolean                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public', 'pg_temp'                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_is_published boolean;                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   v_is_free boolean;                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   v_price numeric;                                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF _user IS NULL OR _course IS NULL THEN                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     RETURN false;                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Admin sempre passa                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   IF public.has_role(_user, 'admin'::public.app_role) THEN                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     RETURN true;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT c.is_published, COALESCE(c.is_free, false), COALESCE(c.price, 0)                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     INTO v_is_published, v_is_free, v_price                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     FROM public.courses c                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |    WHERE c.id = _course;                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF NOT FOUND OR v_is_published IS NOT TRUE THEN                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     RETURN false;                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Curso realmente gratuito                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   IF v_is_free = true OR v_price = 0 THEN                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     RETURN true;                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   -- Curso pago: exige enrollment do próprio usuário                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |   RETURN EXISTS (                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     SELECT 1                                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |       FROM public.enrollments e                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |      WHERE e.user_id = _user                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |        AND e.course_id = _course                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   );                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 has_role                     | _user_id uuid, _role app_role                        | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |  RETURNS boolean                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE sql                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
