 question_bank_coverage       |                                                      | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.question_bank_coverage()                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |  RETURNS TABLE(course_id uuid, course_title text, module_id uuid, module_title text, approved_count bigint, draft_count bigint)                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF NOT public.has_role(auth.uid(),'admin') THEN                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'Forbidden';                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN QUERY                                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     SELECT c.id, c.title, m.id, m.title,                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |            COALESCE(SUM(CASE WHEN q.status='approved' THEN 1 ELSE 0 END),0),                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |            COALESCE(SUM(CASE WHEN q.status='draft'    THEN 1 ELSE 0 END),0)                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       FROM public.courses c                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       LEFT JOIN public.modules m ON m.course_id = c.id                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |       LEFT JOIN public.questions q ON q.module_id = m.id                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |      GROUP BY c.id, c.title, m.id, m.title                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |      ORDER BY c.title, m.title;                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 register_daily_login         |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.register_daily_login()                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  RETURNS TABLE(awarded integer, new_streak integer, new_xp integer)                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_user UUID := auth.uid();                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   v_last DATE;                                                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   v_today DATE := (now() AT TIME ZONE 'UTC')::DATE;                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   v_streak INTEGER;                                                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   v_awarded INTEGER := 0;                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF v_user IS NULL THEN                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |     RAISE EXCEPTION 'Not authenticated';                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   SELECT (last_login_at AT TIME ZONE 'UTC')::DATE, COALESCE(streak,0)                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     INTO v_last, v_streak FROM public.profiles WHERE id = v_user;                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   IF v_last IS NULL OR v_last < v_today THEN                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |     IF v_last = v_today - 1 THEN                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |       v_streak := v_streak + 1;                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     ELSE                                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |       v_streak := 1;                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     UPDATE public.profiles SET last_login_at = now(), streak = v_streak WHERE id = v_user;                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |     PERFORM public.award_xp(v_user, 10, 'daily_login', NULL);                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     v_awarded := 10;                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |     PERFORM public.check_achievements(v_user);                                                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |                                                                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   RETURN QUERY SELECT v_awarded, v_streak, (SELECT xp FROM public.profiles WHERE id = v_user);                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 set_updated_at               |                                                      | f                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.set_updated_at()                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
