 sync_certificate_status      |                                                      | f                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.sync_certificate_status()                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF NEW.revoked_at IS NOT NULL THEN NEW.status := 'revoked';                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   ELSE NEW.status := COALESCE(NEW.status,'issued');                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 sync_profile_level           |                                                      | f                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.sync_profile_level()                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   NEW.level := public.compute_level(NEW.xp);                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
