 validate_certificate         | _code text                                           | t                | s          | search_path=public          | CREATE OR REPLACE FUNCTION public.validate_certificate(_code text)                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             |  RETURNS TABLE(validation_code text, issued_at timestamp with time zone, completion_date date, student_name text, course_title text, course_slug text, track_title text, workload_hours integer, status text, verification_url text, institution_name text, legal_footer text)                                                    +
                              |                                                      |                  |            |                             |  LANGUAGE sql                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |   SELECT c.validation_code, c.issued_at, c.completion_date,                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     COALESCE(c.student_name_snapshot, p.full_name, 'Aluno FCIA'),                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     COALESCE(c.course_title_snapshot, co.title),                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |     co.slug, tr.title,                                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |     COALESCE(c.workload_hours_snapshot, co.workload_hours),                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     c.status, c.verification_url,                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |     s.institution_name, s.legal_footer                                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |   FROM public.certificates c                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             |   JOIN public.courses co ON co.id = c.course_id                                                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |   LEFT JOIN public.tracks tr ON tr.id = co.track_id                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   LEFT JOIN public.profiles p ON p.id = c.user_id                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   CROSS JOIN LATERAL (SELECT institution_name, legal_footer FROM public.certificate_settings WHERE id=1) s                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             |   WHERE c.validation_code = upper(_code)                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |   LIMIT 1;                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 xp_on_certificate            |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.xp_on_certificate()                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | DECLARE                                                                                                                                                                                                                                                                                                                           +
                              |                                                      |                  |            |                             |   v_count INTEGER;                                                                                                                                                                                                                                                                                                                +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   SELECT COUNT(*) INTO v_count FROM public.certificates WHERE user_id = NEW.user_id;                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             |   PERFORM public.award_xp(NEW.user_id, 200, 'course_complete', NEW.course_id);                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |   IF v_count = 1 THEN                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |     PERFORM public.award_xp(NEW.user_id, 100, 'first_course_bonus', NEW.course_id);                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   PERFORM public.check_achievements(NEW.user_id);                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 xp_on_module_complete        |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.xp_on_module_complete()                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF NEW.completed = true AND (OLD IS NULL OR OLD.completed = false) THEN                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |     PERFORM public.award_xp(NEW.user_id, 50, 'module_complete', NEW.module_id);                                                                                                                                                                                                                                                   +
                              |                                                      |                  |            |                             |     PERFORM public.check_achievements(NEW.user_id);                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
                              |                                                      |                  |            |                             | 
 xp_on_quiz_attempt           |                                                      | t                | v          | search_path=public          | CREATE OR REPLACE FUNCTION public.xp_on_quiz_attempt()                                                                                                                                                                                                                                                                            +
                              |                                                      |                  |            |                             |  RETURNS trigger                                                                                                                                                                                                                                                                                                                  +
                              |                                                      |                  |            |                             |  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                 +
                              |                                                      |                  |            |                             |  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                      +
                              |                                                      |                  |            |                             | AS $function$                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | BEGIN                                                                                                                                                                                                                                                                                                                             +
                              |                                                      |                  |            |                             |   IF NEW.passed = true THEN                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     IF NEW.score = 100 THEN                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |       PERFORM public.award_xp(NEW.user_id, 30, 'quiz_perfect', NEW.module_id);                                                                                                                                                                                                                                                    +
                              |                                                      |                  |            |                             |     ELSE                                                                                                                                                                                                                                                                                                                          +
                              |                                                      |                  |            |                             |       PERFORM public.award_xp(NEW.user_id, 10, 'quiz_passed', NEW.module_id);                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             |     END IF;                                                                                                                                                                                                                                                                                                                       +
                              |                                                      |                  |            |                             |     PERFORM public.check_achievements(NEW.user_id);                                                                                                                                                                                                                                                                               +
                              |                                                      |                  |            |                             |   END IF;                                                                                                                                                                                                                                                                                                                         +
                              |                                                      |                  |            |                             |   RETURN NEW;                                                                                                                                                                                                                                                                                                                     +
                              |                                                      |                  |            |                             | END;                                                                                                                                                                                                                                                                                                                              +
                              |                                                      |                  |            |                             | $function$                                                                                                                                                                                                                                                                                                                        +
